const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

module.exports = activity_inspector

async function activity_inspector(opts = {}, protocol, { onClose } = {}) {
  const { sdb } = await get(opts.sid)
  const { drive } = sdb
  const on = { style: inject, data: ondata, icons: onicons }
  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <section class="inspector-page">
      <header class="topbar"><button class="back-button" data-action="back" aria-label="Back">‹</button><div><p>Session journal</p><h1>Activity</h1></div><span class="readonly-badge">Read only</span></header>
      <p class="page-copy">Recent backend requests with their timing, responses, and technical errors.</p>
      <div class="filter-bar"><button class="active" data-filter="all">All</button><button data-filter="success">Success</button><button data-filter="error">Errors</button></div>
      <div class="loading-state"><span class="loading-ring"></span><p>Reading session activity…</p></div>
      <div class="error-state hidden"><span>!</span><strong>Activity unavailable</strong><p></p></div>
      <div class="loaded-state hidden"><div class="activity-summary"></div><div class="activity-list"></div><div class="empty-state hidden"><span>≡</span><strong>No activity recorded</strong><p>Backend requests from this daemon session will appear here.</p></div><p class="captured-at"></p></div>
      <section class="activity-detail hidden"></section>
    </section>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const sendUp = protocol ? protocol(receiveFromParent) : null
  let entries = []
  let capturedAt = ''
  let filter = 'all'
  let loadTimer = null

  await sdb.watch(onbatch)
  shadow.addEventListener('click', handleClick)
  el.open = function () { closeDetail(); load() }
  return el

  function handleClick(event) {
    const action = event.target.closest('[data-action]')
    if (action?.dataset.action === 'back' && onClose) onClose()
    if (action?.dataset.action === 'close-entry') closeDetail()
    const filterButton = event.target.closest('[data-filter]')
    if (filterButton) {
      filter = filterButton.dataset.filter
      shadow.querySelectorAll('[data-filter]').forEach(button => button.classList.toggle('active', button === filterButton))
      renderList()
    }
    const row = event.target.closest('[data-entry-id]')
    if (row) openDetail(row.dataset.entryId)
    const tab = event.target.closest('[data-activity-tab]')
    if (tab) {
      const detail = shadow.querySelector('.activity-detail')
      detail.querySelectorAll('[data-activity-tab]').forEach(button => button.classList.toggle('active', button === tab))
      detail.querySelectorAll('[data-detail-panel]').forEach(panel => panel.classList.toggle('hidden', panel.dataset.detailPanel !== tab.dataset.activityTab))
    }
  }

  function load() {
    if (loadTimer) window.clearTimeout(loadTimer)
    entries = []
    showState('loading')
    request({ type: 'get_diagnostics_activity', data: {} })
    loadTimer = window.setTimeout(function () {
      if (capturedAt) return
      shadow.querySelector('.error-state p').textContent = 'The activity request timed out. Check that the Flamingo backend is running.'
      showState('error')
    }, 8000)
  }

  function receiveFromParent(message) {
    if (message?.type !== 'diagnostics_activity_loaded') return
    if (loadTimer) window.clearTimeout(loadTimer)
    const response = message.data || {}
    if (response.status !== 'success' || !response.data) {
      shadow.querySelector('.error-state p').textContent = String(response.error || 'The backend did not return session activity.')
      showState('error')
      return
    }
    entries = Array.isArray(response.data.entries) ? response.data.entries : []
    capturedAt = response.data.captured_at || ''
    showState('loaded')
    renderList()
  }

  function renderList() {
    const errors = entries.filter(entry => entry.status === 'error').length
    const successful = entries.length - errors
    shadow.querySelector('.activity-summary').innerHTML = `${summaryMetric('Requests', entries.length)}${summaryMetric('Succeeded', successful, 'green')}${summaryMetric('Errors', errors, errors ? 'red' : '')}`
    const visible = entries.filter(entry => filter === 'all' || (filter === 'error' ? entry.status === 'error' : entry.status !== 'error'))
    shadow.querySelector('.activity-list').innerHTML = visible.map(function (entry) {
      const failed = entry.status === 'error'
      return `<button class="activity-row" data-entry-id="${escapeHtml(entry.id || '')}"><span class="activity-icon ${failed ? 'failed' : 'passed'}">${failed ? '!' : '✓'}</span><span class="activity-copy"><strong>${escapeHtml(displayIntent(entry.intent))}</strong><small>${escapeHtml(entry.node_id || 'Application')} · ${formatTime(entry.timestamp)}</small>${entry.error ? `<em>${escapeHtml(entry.error)}</em>` : ''}</span><span class="duration">${formatDuration(entry.duration_ms)}</span><span class="chevron">›</span></button>`
    }).join('')
    shadow.querySelector('.empty-state').classList.toggle('hidden', visible.length !== 0)
    const time = new Date(capturedAt)
    shadow.querySelector('.captured-at').textContent = capturedAt ? `Journal read ${Number.isNaN(time.getTime()) ? capturedAt : time.toLocaleString()}` : ''
  }

  function openDetail(id) {
    const entry = entries.find(item => String(item.id) === String(id))
    if (!entry) return
    const failed = entry.status === 'error'
    const detail = shadow.querySelector('.activity-detail')
    detail.innerHTML = `
      <header class="detail-header"><button data-action="close-entry" aria-label="Back to activity">‹</button><div><small>Request details</small><strong>${escapeHtml(displayIntent(entry.intent))}</strong></div><span class="status-pill ${failed ? 'failed' : 'passed'}">${failed ? 'Error' : 'Success'}</span></header>
      <article class="request-meta">${row('Target', entry.node_id || 'Application')}${row('Started', formatDate(entry.timestamp))}${row('Duration', formatDuration(entry.duration_ms))}${row('Operation', entry.intent || 'Unknown')}</article>
      ${entry.error ? `<div class="technical-error"><strong>Technical error</strong><p>${escapeHtml(entry.error)}</p></div>` : ''}
      <div class="content-tabs"><button class="active" data-activity-tab="response">Response</button><button data-activity-tab="request">Request</button></div>
      <div class="json-panel" data-detail-panel="response"><pre>${escapeHtml(JSON.stringify(entry.response ?? { status: entry.status, error: entry.error || '' }, null, 2))}</pre></div>
      <div class="json-panel hidden" data-detail-panel="request"><pre>${escapeHtml(JSON.stringify(entry.request ?? {}, null, 2))}</pre></div>
      <p class="privacy-copy">Sensitive wallet material is redacted before activity is stored.</p>
    `
    shadow.querySelector('.loaded-state').classList.add('hidden')
    shadow.querySelector('.filter-bar').classList.add('hidden')
    shadow.querySelector('.page-copy').classList.add('hidden')
    detail.classList.remove('hidden')
    shadow.querySelector('.inspector-page').scrollTop = 0
  }

  function closeDetail() {
    shadow.querySelector('.activity-detail').classList.add('hidden')
    shadow.querySelector('.filter-bar').classList.remove('hidden')
    shadow.querySelector('.page-copy').classList.remove('hidden')
    if (entries.length || capturedAt) shadow.querySelector('.loaded-state').classList.remove('hidden')
  }

  function showState(state) {
    shadow.querySelector('.loading-state').classList.toggle('hidden', state !== 'loading')
    shadow.querySelector('.error-state').classList.toggle('hidden', state !== 'error')
    shadow.querySelector('.loaded-state').classList.toggle('hidden', state !== 'loaded')
  }
  function request(message) { if (typeof sendUp === 'function') sendUp({ from: 'activity_inspector', ...message }) }
  function summaryMetric(label, value, tone) { return `<div class="summary-metric ${tone || ''}"><strong>${value}</strong><small>${label}</small></div>` }
  function row(label, value) { return `<div class="meta-row"><span>${label}</span><strong>${escapeHtml(String(value))}</strong></div>` }
  function displayIntent(intent) { return String(intent || 'unknown request').replace(/_/g, ' ').replace(/\b\w/g, char => char.toUpperCase()) }
  function formatTime(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? 'Unknown time' : date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }) }
  function formatDate(value) { const date = new Date(value); return Number.isNaN(date.getTime()) ? String(value || 'Unknown') : date.toLocaleString() }
  function formatDuration(value) { return Number.isFinite(Number(value)) ? `${Number(value).toLocaleString()} ms` : '—' }
  function escapeHtml(value) { return String(value).replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[char]) }
  async function onbatch(batch) { for (const { type, paths } of batch) { const data = await Promise.all(paths.map(path => drive.get(path).then(file => file.raw))); await (on[type] || fail)(data, type) } }
  function inject(data) { style.textContent = data[0] }
  function ondata() {}
  function onicons() {}
  function fail(data, type) { throw new Error('invalid message', { cause: { data, type } }) }
}

function fallback_module() {
  return { api: fallback_instance }
  function fallback_instance(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}
    return { drive: { 'icons/': {}, 'style/': { 'style.css': { '$ref': 'activity_inspector.css' } }, 'data/': { 'opts.json': { raw: opts || {} } } } }
  }
}
